SELECT 

WHERE staff.tenant_id =
      #{tenantId,typeHandler=com.rigour.tenant.iam.infrastructure.persistence.typehandler.UuidBinaryTypeHandler}
  AND staff.id =
      #{id,typeHandler=com.rigour.tenant.iam.infrastructure.persistence.typehandler.UuidBinaryTypeHandler}
  AND staff.deleted_at IS NULL

SELECT 

WHERE staff.tenant_id =
      #{tenantId,typeHandler=com.rigour.tenant.iam.infrastructure.persistence.typehandler.UuidBinaryTypeHandler}
  AND staff.deleted_at IS NULL
  AND source_binding.source_system = 'DINGHUOBAO'
  AND source_binding.source_tenant_key = #{sourceTenantKey}
  AND source_binding.source_presence = 'PRESENT'
  AND (
      1 = 0

          OR source_binding.source_staff_id IN

              #{sourceStaffId}



          OR staff.staff_name IN

              #{sourceStaffName}

          OR source_binding.source_account_name IN

              #{sourceStaffName}

          OR user_record.display_name IN

              #{sourceStaffName}


  )
ORDER BY

  CASE WHEN source_binding.source_staff_id IN

          #{sourceStaffId}

      THEN 0 ELSE 1 END,

  staff.employment_status = 'ACTIVE' DESC,
  staff.updated_at DESC,
  staff.staff_code
